    try {
      const raw = GM_getValue(ARCHIVE_METADATA_STORE_KEY, '');
      if (!raw) {
        _cachedVerifiedArchiveStore = { version: 1, projects: {} };
        return _cachedVerifiedArchiveStore;
      }
      const parsed = JSON.parse(String(raw));

